    cutlist(context, id + "cutlist1", { "selectAllFrames" : false, "frames" : qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID), "columnOverrides" : [{ "isFirst" : true, "overrideAllFrames" : true, "column" : "Description", "value" : "Rail" }] });
    return { "composites" : evaluateQueryCount(context, qBodyType(qCreatedBy(id + "cutlist1", EntityType.BODY), BodyType.COMPOSITE)), "table" : caseTables(context, id, cutlistTable(context, {})) };
