// fit-spline: through three vertices, along x at the start and y at the end, matching curvature at both
export function c005(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const dirX = newSketchOnPlane(context, id + "dirX", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(dirX, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirX);
    const dirY = newSketchOnPlane(context, id + "dirY", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(dirY, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirY);
    fitSpline(context, id + "spline1", { "vertices" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(0, 0, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(30, 0, 10) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.VERTEX), vector(30, 20, 0) * millimeter)]), "hasStartDirection" : true, "startDirection" : qCreatedBy(id + "dirX", EntityType.EDGE), "startMagnitude" : 1, "matchStartCurvature" : true, "hasEndDirection" : true, "endDirection" : qCreatedBy(id + "dirY", EntityType.EDGE), "endMagnitude" : 1, "matchEndCurvature" : true });
}

// isocline: the 30 degree isoclines of a cylinder lying along y, as curves
export function c006(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const up = newSketchOnPlane(context, id + "up", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(up, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(up);
    isocline(context, id + "iso1", { "faces" : qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "direction" : qCreatedBy(id + "up", EntityType.EDGE), "oppositeDirection" : false, "angle" : 30 * degree, "split" : false });
}
